		ListView4.Items.Clear();
		ComboBox5.Items.Clear();
		sjka_cyber.cList2 = new List<string>();
		string hTML = new GetHtmlClass(Module1._dburl + "/get.php?t=cList2").getHTML(MyProject.Forms.mlas);
		if (Operators.CompareString(hTML, "incorrect", TextCompare: false) == 0)
		{
			CustomMsgBox.CMsgBox("잠시 후에 다시 시도하십시오.\r\n이런 현상이 계속되면 MLAS를 종료하고 재시작 하십시오.", "통신대기 발생", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error, custom_msgbox.ShowLocation.BottomRight, autoClose: true, 3000);
			return;
		}
		string[] array = hTML.Split(new string[1] { "||" }, StringSplitOptions.RemoveEmptyEntries);
		foreach (string item in array)
		{
			sjka_cyber.cList2.Add(item);
		}
		acc_cource2.Items.Clear();
		string hTML2 = new GetHtmlClass(Module1._dburl + "/get.php?t=catList2").getHTML(MyProject.Forms.mlas);
		if (Operators.CompareString(hTML2, "incorrect", TextCompare: false) == 0)
		{
			CustomMsgBox.CMsgBox("잠시 후에 다시 시도하십시오.\r\n이런 현상이 계속되면 MLAS를 종료하고 재시작 하십시오.", "통신대기 발생", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error, custom_msgbox.ShowLocation.BottomRight, autoClose: true, 3000);
			return;
		}
		string[] array2 = hTML2.Split(new string[1] { "||" }, StringSplitOptions.RemoveEmptyEntries);
		checked
		{
			for (int j = 0; j < array2.Length; j++)
			{
				string[] array3 = array2[j].Split(new string[1] { "**" }, StringSplitOptions.RemoveEmptyEntries);
				ComboBox5.Items.Add(Conversion.Val(array3[0]).ToString("(C0####) ") + array3[1]);
				courseListArray.Add(new sjka_cyber_course(array3[0], array3[1].Trim()));
				acc_cource2.Items.Add(array3[1]);
			}
			acc_cource.Items.Clear();
			string hTML3 = new GetHtmlClass(Module1._dburl + "/get.php?t=clist", null, progress: true).getHTML(MyProject.Forms.mlas);
			hTML3 = "무료" + hTML3;
			int num = 0;
			string[] array4 = hTML3.Split(new string[1] { "||" }, StringSplitOptions.RemoveEmptyEntries);
			foreach (string text in array4)
			{
				if (num == 0)
				{
					ListView4.Items.Add(Conversions.ToString(1));
					ListView4.Items[0].SubItems.Add("무료");
					int num2 = sjka_cyber.cList2.Count - 1;
					for (int l = 0; l <= num2; l++)
					{
						if (Operators.CompareString(sjka_cyber.cList2[l].Trim(), null, TextCompare: false) != 0)
						{
							string[] array5 = sjka_cyber.cList2[l].Trim().Split(new string[1] { "**" }, StringSplitOptions.None);
							if (Operators.CompareString(text.Trim(), array5[1].Trim(), TextCompare: false) == 0)
							{
								ListView4.Items[num].SubItems.Add(array5[2]);
								break;
							}
						}
					}
					num++;
				}
				if (num == 0)
				{
					continue;
				}
				bool flag = false;
				try
				{
					int num3 = ListView4.Items.Count - 1;
					for (int m = 0; m <= num3; m++)
					{
						if (Operators.CompareString(ListView4.Items[m].SubItems[1].Text, text, TextCompare: false) == 0)
						{
							flag = true;
							break;
						}
					}
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception ex2 = ex;
					ProjectData.ClearProjectError();
				}
				if (flag)
				{
					continue;
				}
				ListView4.Items.Add(Conversions.ToString(num + 1));
				ListView4.Items[num].SubItems.Add(text);
				acc_cource.Items.Add(text);
				int num4 = sjka_cyber.cList2.Count - 1;
				for (int n = 0; n <= num4; n++)
				{
					if (Operators.CompareString(sjka_cyber.cList2[n].Trim(), null, TextCompare: false) != 0)
					{
						string[] array6 = sjka_cyber.cList2[n].Trim().Split(new string[1] { "**" }, StringSplitOptions.None);
						if (Operators.CompareString(text.Trim(), array6[1].Trim(), TextCompare: false) == 0)
						{
							ListView4.Items[num].SubItems.Add(array6[2]);
							break;
						}
					}
				}
				num++;
			}
		}
	}

	private void ListView4_SelectedIndexChanged(object sender, EventArgs e)
	{
		try
		{
			TextBox8.Text = ListView4.SelectedItems[0].SubItems[1].Text;
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
		try
		{
			ListBox14.Items.Clear();
			string text = ListView4.SelectedItems[0].SubItems[2].Text;
			string[] array = text.Split(new string[1] { "," }, StringSplitOptions.RemoveEmptyEntries);
			TextBox4.Text = text;
			string[] array2 = array;
			IEnumerator enumerator = default(IEnumerator);
			foreach (string value in array2)
			{
				try
				{
					enumerator = ComboBox5.Items.GetEnumerator();
					while (enumerator.MoveNext())
					{
						string text2 = Conversions.ToString(enumerator.Current);
						if (text2.Substring(1, text2.IndexOf(")")).Contains(value))
						{
							ListBox14.Items.Add(text2);
							break;
						}
					}
				}
				finally
				{
					if (enumerator is IDisposable)
					{
						(enumerator as IDisposable).Dispose();
					}
				}
			}
		}
		catch (Exception ex3)
		{
			ProjectData.SetProjectError(ex3);
			Exception ex4 = ex3;
			TextBox4.Text = null;
			ListBox14.Items.Clear();
			ProjectData.ClearProjectError();
		}
		Panel96.Visible = true;
	}

	public void docList(bool refresh = false)
	{
		sjka_cyber.docs = new List<DocData>();
		if (Operators.ConditionalCompareObjectEqual(refresh, true, TextCompare: false))
		{
			ComboBox1.Text = null;
			ListBox1.Items.Clear();
			ComboBox2.Items.Clear();
		}
		string hTML = new GetHtmlClass(Module1._dburl + "/get.php?t=docsGroup", null, progress: true).getHTML(MyProject.Forms.mlas);
		if (Operators.CompareString(hTML, "incorrect", TextCompare: false) == 0)
		{
			CustomMsgBox.CMsgBox("잠시 후에 다시 시도하십시오.\r\n이런 현상이 계속되면 MLAS를 종료하고 재시작 하십시오.", "통신대기 발생", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error, custom_msgbox.ShowLocation.BottomRight, autoClose: true, 3000);
			return;
		}
		ComboBoxEx3.Items.Clear();
		docsGroup.Items.Clear();
		ComboBoxEx1.Items.Clear();
		string[] array = hTML.Split(new string[1] { "<split>" }, StringSplitOptions.RemoveEmptyEntries);
		foreach (string item in array)
		{
			ComboBoxEx3.Items.Add(item);
			docsGroup.Items.Add(item);
			ComboBoxEx1.Items.Add(item);
		}
		if (Conversions.ToBoolean(Operators.OrObject(Operators.CompareString(ComboBox2.Text, null, TextCompare: false) == 0, Operators.CompareObjectEqual(refresh, true, TextCompare: false))))
		{
			ComboBox2.Items.Clear();
			hTML = new GetHtmlClass(Module1._dburl + "/get.php?t=docsList", null, progress: true).getHTML(MyProject.Forms.mlas);
			if (Operators.CompareString(hTML, "incorrect", TextCompare: false) == 0)
			{
				CustomMsgBox.CMsgBox("잠시 후에 다시 시도하십시오.\r\n이런 현상이 계속되면 MLAS를 종료하고 재시작 하십시오.", "통신대기 발생", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error, custom_msgbox.ShowLocation.BottomRight, autoClose: true, 3000);
				return;
			}
			string[] array2 = hTML.Split(new string[1] { "<split>" }, StringSplitOptions.RemoveEmptyEntries);
			for (int j = 0; j < array2.Length; j = checked(j + 1))
			{
				string[] array3 = array2[j].Split(new string[1] { "<separate>" }, StringSplitOptions.RemoveEmptyEntries);
				sjka_cyber.docs.Add(new DocData(array3[0], array3[1], array3[2], array3[3], Conversions.ToInteger(array3[4])));
				ComboBox2.Items.Add(Conversion.Val(array3[0]).ToString("(D0####) ") + array3[2]);
			}
		}
		ComboBoxEx3.SelectedIndex = 0;
		docsGroup.SelectedIndex = docNowGroup;
	}

