	private void ComboBox2_SelectedIndexChanged(object sender, EventArgs e)
	{
		NewLateBinding.LateCall(sender, null, "invalidate", new object[0], null, null, null, IgnoreReturn: true);
		if (saveBool)
		{
			saveBool = false;
			return;
		}
		if (Operators.CompareString(ComboBox2.Text, null, TextCompare: false) == 0)
		{
			Button2.Visible = false;
			Button10.Visible = false;
			Button5.Visible = false;
			Button120.Visible = false;
			Button120.Visible = false;
		}
		else
		{
			Button2.Visible = true;
			Button10.Visible = true;
			Button5.Visible = true;
			Button120.Visible = true;
			Button120.Visible = true;
		}
		ComboBox1.Items.Clear();
		checked
		{
			DocData docData = sjka_cyber.docs.Find((DocData a) => ((double)a.Index == Conversion.Val(ComboBox2.SelectedItem.ToString().Substring(2, ComboBox2.SelectedItem.ToString().IndexOf(")") - 1))) ? true : false);
			TextBox2.Text = docData.Name;
			TextBox1.Text = null;
			ComboBoxEx1.Text = docData.Group;
			int num = docData.Count() - 1;
			for (int i = 0; i <= num; i++)
			{
				ComboBox1.Items.Add(Conversions.ToString(i + 1) + " 과목 [" + docData.getSubjectName(i) + "]");
				TextBox textBox;
				(textBox = TextBox1).Text = textBox.Text + docData.getSubjectName(i) + "/";
			}
			TextBox1.Text = TextBox1.Text.Remove(TextBox1.Text.Length - 1);
			if (docData.Silgi)
			{
				RadioButton5.Checked = true;
			}
			else
			{
				RadioButton6.Checked = true;
			}
			if (!docData.Available())
			{
				string hTML = new GetHtmlClass(Module1._dburl + "/get.php?t=docsReturn&n=" + Conversions.ToString(docData.Index), null, progress: true).getHTML(MyProject.Forms.mlas);
				int num2 = 0;
				string[] array = hTML.Trim().Split(new string[1] { "<subject>" }, StringSplitOptions.RemoveEmptyEntries);
				foreach (string obj in array)
				{
					int num3 = 0;
					string[] array2 = obj.Trim().Split(new string[1] { "<question>" }, StringSplitOptions.RemoveEmptyEntries);
					foreach (string text in array2)
					{
						num3++;
						if (!docData.SubjectItems(num2).Add(text.Trim()))
						{
							CustomMsgBox.CMsgBox("추가 실패 (제작사에 문의하십시오.)\r\n내용: " + text, "알 수 없는 오류가 발생하였습니다.", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
						}
					}
					num2++;
				}
			}
			ComboBox1.Text = null;
			ComboBox1.SelectedIndex = 0;
			TabControl2.Show();
			Panel4.Visible = true;
			string text2 = null;
			foreach (DocData.SubjectData item in docData.SubjectItems())
			{
				text2 += "<subject>\r\n";
				int num4 = item.Count() - 1;
				for (int l = 0; l <= num4; l++)
				{
					text2 += "<question>\r\n";
					text2 = ((Operators.CompareString(item.getQuestion(l).A_question, null, TextCompare: false) != 0) ? (text2 + item.getQuestion(l).A_question.Replace("\r\n", "<enter>").Replace("<sp>", " ") + "\r\n") : (text2 + "null\r\n"));
					text2 = ((Operators.CompareString(item.getQuestion(l).B_subtext, null, TextCompare: false) != 0) ? (text2 + item.getQuestion(l).B_subtext.Replace("\r\n", "<enter>").Replace("<sp>", " ") + "\r\n") : (text2 + "null\r\n"));
					text2 = ((Operators.CompareString(item.getQuestion(l).C_answer1, null, TextCompare: false) != 0) ? (text2 + item.getQuestion(l).C_answer1.Replace("\r\n", "<enter>").Replace("<sp>", " ") + "\r\n") : (text2 + "null\r\n"));
					text2 = ((Operators.CompareString(item.getQuestion(l).D_answer2, null, TextCompare: false) != 0) ? (text2 + item.getQuestion(l).D_answer2.Replace("\r\n", "<enter>").Replace("<sp>", " ") + "\r\n") : (text2 + "null\r\n"));
					text2 = ((Operators.CompareString(item.getQuestion(l).E_answer3, null, TextCompare: false) != 0) ? (text2 + item.getQuestion(l).E_answer3.Replace("\r\n", "<enter>").Replace("<sp>", " ") + "\r\n") : (text2 + "null\r\n"));
					text2 = ((Operators.CompareString(item.getQuestion(l).F_answer4, null, TextCompare: false) != 0) ? (text2 + item.getQuestion(l).F_answer4.Replace("\r\n", "<enter>").Replace("<sp>", " ") + "\r\n") : (text2 + "null\r\n"));
					text2 = ((Operators.CompareString(item.getQuestion(l).G_answer5, null, TextCompare: false) != 0) ? (text2 + item.getQuestion(l).G_answer5.Replace("\r\n", "<enter>").Replace("<sp>", " ") + "\r\n") : (text2 + "null\r\n"));
					text2 = ((item.getQuestion(l).H_correct != 0) ? (text2 + Conversions.ToString(item.getQuestion(l).H_correct) + "\r\n") : (text2 + "null\r\n"));
					text2 = ((Operators.CompareString(item.getQuestion(l).I_exp, null, TextCompare: false) != 0) ? (text2 + item.getQuestion(l).I_exp.Replace("\r\n", "<enter>").Replace("<sp>", " ") + "\r\n\r\n") : (text2 + "null\r\n\r\n"));
					Application.DoEvents();
				}
			}
			RichTextbox1.Text = text2.Trim().Replace("     ", "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;").Replace("    ", "&nbsp;&nbsp;&nbsp;&nbsp;")
				.Replace("   ", "&nbsp;&nbsp;&nbsp;")
				.Replace("  ", "&nbsp;&nbsp;");
			rtbBarInit();
		}
	}

