	private void Button9_Click(object sender, EventArgs e)
	{
		checked
		{
			DocData docData = sjka_cyber.docs.Find((DocData a) => ((double)a.Index == Conversion.Val(ComboBox2.SelectedItem.ToString().Substring(2, ComboBox2.SelectedItem.ToString().IndexOf(")") - 1))) ? true : false);
