			int selectedIndex = ListBox1.SelectedIndex;
			subjectData.setQuestion(selectedIndex, DocData.SubjectData.QuestionData.Type.A_Question, q1.Text);
			subjectData.setQuestion(selectedIndex, DocData.SubjectData.QuestionData.Type.B_subtext, e1.Text);
			subjectData.setQuestion(selectedIndex, DocData.SubjectData.QuestionData.Type.C_answer1, n1.Text);
			subjectData.setQuestion(selectedIndex, DocData.SubjectData.QuestionData.Type.D_answer2, n2.Text);
			subjectData.setQuestion(selectedIndex, DocData.SubjectData.QuestionData.Type.E_answer3, n3.Text);
			subjectData.setQuestion(selectedIndex, DocData.SubjectData.QuestionData.Type.F_answer4, n4.Text);
			subjectData.setQuestion(selectedIndex, DocData.SubjectData.QuestionData.Type.G_answer5, n5.Text);
			int num = 0;
			if (r1.Checked)
			{
				num = 1;
			}
			if (r2.Checked)
			{
				num = 2;
			}
			if (r3.Checked)
			{
				num = 3;
			}
			if (r4.Checked)
			{
				num = 4;
			}
			if (r5.Checked)
			{
				num = 5;
			}
			subjectData.setQuestion(selectedIndex, DocData.SubjectData.QuestionData.Type.H_correct, Conversions.ToString(num));
			subjectData.setQuestion(selectedIndex, DocData.SubjectData.QuestionData.Type.I_exp, h1.Text);
			int num2 = 0;
			int num3 = docData.SubjectItems().Count - 1;
			for (int i = 0; i <= num3; i++)
			{
				if (ComboBox1.SelectedIndex == 0)
				{
					break;
				}
				DocData.SubjectData subjectData2 = docData.SubjectItems(i);
				num2 += subjectData2.Count();
				if (i >= ComboBox1.SelectedIndex - 1)
				{
					break;
				}
			}
			try
			{
				saveBool = true;
				ListBox1.Items[selectedIndex] = Conversions.ToString(num2 + selectedIndex + 1) + ". " + q1.Text.Trim();
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ProjectData.ClearProjectError();
			}
