	private void Button8_MouseDown(object sender, MouseEventArgs e)
	{
		object obj = ((sender != Button8) ? h1 : e1);
		Button9.BackColor = Color.Red;
		Button9.BackgroundImage = Resources.public_button;
		TextBox textBox = (TextBox)obj;
		int selectionStart = textBox.SelectionStart;
		bool flag = true;
		try
		{
			int num = textBox.Text.Substring(selectionStart).IndexOf(">");
			int num2 = textBox.Text.Substring(selectionStart).IndexOf("<");
			flag = ((num <= num2) ? true : false);
			flag = ((!(num == -1 && num2 == -1)) ? true : false);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
		int num3 = -1;
		string search = null;
		if (flag)
		{
			try
			{
				num3 = textBox.Text.Substring(0, selectionStart).LastIndexOf("<");
				flag = num3 > -1;
			}
			catch (Exception ex3)
			{
				ProjectData.SetProjectError(ex3);
				Exception ex4 = ex3;
				flag = false;
				ProjectData.ClearProjectError();
			}
		}
		if (flag)
		{
			try
			{
				if (Operators.CompareString(textBox.Text.Substring(num3, textBox.Text.Substring(num3).IndexOf("=")).Trim(), "<img id", TextCompare: false) == 0)
				{
					flag = true;
				}
				else
				{
					flag = false;
				}
				search = checked(textBox.Text.Substring(num3 + 8, textBox.Text.Substring(num3 + 8).IndexOf(" ")));
			}
			catch (Exception ex5)
			{
				ProjectData.SetProjectError(ex5);
				Exception ex6 = ex5;
				flag = false;
				ProjectData.ClearProjectError();
			}
		}
		Module1.FManagerShowV2(p2, RuntimeHelpers.GetObjectValue(obj), search);
	}

	private void Button2_Click(object sender, EventArgs e)
	{
		checked
		{
			DocData docData = sjka_cyber.docs.Find((DocData a) => ((double)a.Index == Conversion.Val(ComboBox2.SelectedItem.ToString().Substring(2, ComboBox2.SelectedItem.ToString().IndexOf(")") - 1))) ? true : false);
			string text = null;
			foreach (DocData.SubjectData item in docData.SubjectItems())
			{
				text += "<subject>\r\n";
				int num = item.Count() - 1;
				for (int i = 0; i <= num; i++)
				{
					text += "<question>\r\n";
					text = ((Operators.CompareString(item.getQuestion(i).A_question, null, TextCompare: false) != 0) ? (text + item.getQuestion(i).A_question.Replace("\r\n", "<enter>").Replace("<sp>", " ") + "\r\n") : (text + "null\r\n"));
					text = ((Operators.CompareString(item.getQuestion(i).B_subtext, null, TextCompare: false) != 0) ? (text + item.getQuestion(i).B_subtext.Replace("\r\n", "<enter>").Replace("<sp>", " ") + "\r\n") : (text + "null\r\n"));
					text = ((Operators.CompareString(item.getQuestion(i).C_answer1, null, TextCompare: false) != 0) ? (text + item.getQuestion(i).C_answer1.Replace("\r\n", "<enter>").Replace("<sp>", " ") + "\r\n") : (text + "null\r\n"));
