					text = ((Operators.CompareString(item.getQuestion(i).E_answer3, null, TextCompare: false) != 0) ? (text + item.getQuestion(i).E_answer3.Replace("\r\n", "<enter>").Replace("<sp>", " ") + "\r\n") : (text + "null\r\n"));
