					text = ((Operators.CompareString(item.getQuestion(i).I_exp, null, TextCompare: false) != 0) ? (text + item.getQuestion(i).I_exp.Replace("\r\n", "<enter>").Replace("<sp>", " ") + "\r\n\r\n") : (text + "null\r\n\r\n"));
