	private string MarkFindReplace(string arg)
	{
		int num = arg.IndexOf('"');
		if (num < 0)
		{
			return arg;
		}
		checked
		{
			try
			{
				string text = arg.Substring(0, num);
				string text2 = arg.Substring(num + 1, arg.Length - num - 1);
				text2 = text2.Substring(0, text2.IndexOf('"'));
				string text3 = arg.Substring(text.Length + text2.Length + 2);
				return MarkFindReplace(text + text2.Replace(",", "<comma>") + text3);
			}
			catch (ArgumentOutOfRangeException ex)
			{
				ProjectData.SetProjectError(ex);
				ArgumentOutOfRangeException ex2 = ex;
				string result = arg.Replace("\"", "");
				ProjectData.ClearProjectError();
				return result;
			}
		}
	}

