	private void numClick(object sender, EventArgs e)
	{
		object obj = null;
		object left = NewLateBinding.LateGet(sender, null, "name", new object[0], null, null, null);
		if (Operators.ConditionalCompareObjectEqual(left, nbtn1.Name, TextCompare: false))
		{
			obj = n1;
		}
		else if (Operators.ConditionalCompareObjectEqual(left, nbtn2.Name, TextCompare: false))
		{
			obj = n2;
		}
		else if (Operators.ConditionalCompareObjectEqual(left, nbtn3.Name, TextCompare: false))
		{
			obj = n3;
		}
		else if (Operators.ConditionalCompareObjectEqual(left, nbtn4.Name, TextCompare: false))
		{
			obj = n4;
		}
		else if (Operators.ConditionalCompareObjectEqual(left, nbtn5.Name, TextCompare: false))
		{
			obj = n5;
		}
		TextBox textBox = (TextBox)obj;
		int selectionStart = textBox.SelectionStart;
		bool flag = true;
		try
		{
			int num = textBox.Text.Substring(selectionStart).IndexOf(">");
			int num2 = textBox.Text.Substring(selectionStart).IndexOf("<");
			flag = ((num <= num2) ? true : false);
			flag = ((!(num == -1 && num2 == -1)) ? true : false);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
		int num3 = -1;
		string search = null;
		if (flag)
		{
			try
			{
				num3 = textBox.Text.Substring(0, selectionStart).LastIndexOf("<");
				if (num3 > -1)
				{
					flag = true;
				}
				else
				{
					flag = false;
				}
			}
			catch (Exception ex3)
			{
				ProjectData.SetProjectError(ex3);
				Exception ex4 = ex3;
				flag = false;
				ProjectData.ClearProjectError();
			}
			try
			{
				if (Operators.CompareString(textBox.Text.Substring(num3, textBox.Text.Substring(num3).IndexOf("=")).Trim(), "<img id", TextCompare: false) == 0)
				{
					flag = true;
				}
				else
				{
					flag = false;
				}
			}
			catch (Exception ex5)
			{
				ProjectData.SetProjectError(ex5);
				Exception ex6 = ex5;
				flag = false;
				ProjectData.ClearProjectError();
			}
			search = checked(textBox.Text.Substring(num3 + 8, textBox.Text.Substring(num3 + 8).IndexOf(" ")));
		}
		Module1.FManagerShowV2(p2, RuntimeHelpers.GetObjectValue(obj), search);
	}

