		if (Operators.CompareString(hTML, "incorrect", TextCompare: false) == 0)
		{
			CustomMsgBox.CMsgBox("잠시 후에 다시 시도하십시오.\r\n이런 현상이 계속되면 MLAS를 종료하고 재시작 하십시오.", "통신대기 발생", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error, custom_msgbox.ShowLocation.BottomRight, autoClose: true, 3000);
			return;
		}
		ZipArray = hTML.Split(new string[1] { "||" }, StringSplitOptions.RemoveEmptyEntries);
		ComboBox4.Items.Clear();
		diag_copyKeyword_combobox.Items.Clear();
		TextBox5.Text = null;
		ListView1.Items.Clear();
		Panel32.Enabled = false;
		string[] zipArray = ZipArray;
		for (int i = 0; i < zipArray.Length; i = checked(i + 1))
		{
			string[] array = zipArray[i].Trim().Split(new string[1] { "**" }, StringSplitOptions.RemoveEmptyEntries);
			ComboBox4.Items.Add(Conversion.Val(array[0]).ToString("(W0####) ") + array[1]);
			diag_copyKeyword_combobox.Items.Add(Conversion.Val(array[0]).ToString("(W0####) ") + array[1]);
			sjka_cyber.ZipList_dl.Add(new DataLibrary(array[0], array[1], array[2]));
		}
		SplitContainer2.Panel2Collapsed = true;
	}

