	private void PictureBox10_MouseDown(object sender, MouseEventArgs e)
	{
		if (MessageBox.Show("이미지를 삭제 하시겠습니까? 다시 복구할 수 없습니다.", "이미지 삭제 확인", MessageBoxButtons.YesNo, MessageBoxIcon.Exclamation) == DialogResult.No)
		{
			return;
		}
		checked
		{
			this.num = (int)Math.Round(Conversion.Val(TextBox9.Text));
			index = NewLateBinding.LateGet(sender, null, "name", new object[0], null, null, null).ToString().Substring(NewLateBinding.LateGet(sender, null, "name", new object[0], null, null, null).ToString().LastIndexOf("x") + 1);
			if (Operators.CompareString(new GetHtmlClass(Module1._dburl + "/set.php?t=DELimage&p=" + MySettingsProperty.Settings.pw + "&index=" + index + "&n=" + Conversions.ToString(this.num)).getHTML(MyProject.Forms.mlas), "correct", TextCompare: false) != 0)
			{
				return;
			}
			int num = new GetHtmlClass(Module1._dburl + "/get.php?t=KeyImageN&n=" + Conversions.ToString(this.num)).getHTML(MyProject.Forms.mlas).Split(new string[1] { "|" }, StringSplitOptions.None).Length - 1;
			for (int i = 0; i <= num; i++)
			{
				PictureBox pictureBox = null;
				switch (i)
				{
				case 0:
					pictureBox = img1;
					break;
				case 1:
					pictureBox = img2;
					break;
				case 2:
					pictureBox = img3;
					break;
				case 3:
					pictureBox = img4;
					break;
				case 4:
					pictureBox = img5;
					break;
				case 5:
					pictureBox = img6;
					break;
				case 6:
					pictureBox = img7;
					break;
				case 7:
					pictureBox = img8;
					break;
				case 8:
					pictureBox = img9;
					break;
				case 9:
					pictureBox = img10;
					break;
				}
				try
				{
					byte[] buffer = Convert.FromBase64String(new GetHtmlClass(Module1._dburl + "/get.php?t=KeyImageN&n=" + Conversions.ToString(this.num) + "&d=" + Conversions.ToString(i + 1)).getHTML(MyProject.Forms.mlas));
					MemoryStream stream = new MemoryStream(buffer);
					pictureBox.Image = Image.FromStream(stream);
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception ex2 = ex;
					pictureBox.Image = null;
					GC.Collect();
					ProjectData.ClearProjectError();
				}
			}
		}
	}

