	private void TextBox29_KeyDown(object sender, KeyEventArgs e)
	{
		object[] array = new object[1];
		array[0] = NewLateBinding.LateGet(sender, null, "SelectionStart", new object[0], null, null, null);
		object[] array2 = array;
		bool[] obj = new bool[1] { true };
		bool[] array3 = obj;
		object value = NewLateBinding.LateGet(sender, null, "GetLineFromCharIndex", array, null, null, obj);
		if (array3[0])
		{
			NewLateBinding.LateSetComplex(sender, null, "SelectionStart", new object[1] { array2[0] }, null, null, OptimisticSet: true, RValueBase: false);
		}
		Conversions.ToInteger(value);
		object obj2 = NewLateBinding.LateGet(sender, null, "GetPositionFromCharIndex", new object[1] { Operators.SubtractObject(NewLateBinding.LateGet(sender, null, "SelectionStart", new object[0], null, null, null), 1) }, null, null, null);
		Point location = ((obj2 != null) ? ((Point)obj2) : default(Point));
		checked
		{
			location.Y += 40;
			if (!initcodelistbox)
			{
				initcodelistbox = true;
				codeListbox = new ListBox();
				ListBox listBox = codeListbox;
				listBox.BorderStyle = BorderStyle.FixedSingle;
				listBox.Width = 100;
				listBox.Height = 100;
				listBox.Sorted = true;
				listBox.Items.Add("font");
				listBox.Items.Add("center");
				listBox.Items.Add("ul");
				listBox.Items.Add("ol");
				listBox.Items.Add("br");
				listBox.Items.Add("p");
				listBox.Items.Add("hr");
				listBox.Items.Add("a");
				listBox.Items.Add("q");
				listBox.Items.Add("table");
				listBox.Items.Add("tr");
				listBox.Items.Add("td");
				listBox.Items.Add("div");
				listBox.Items.Add("li");
				listBox.Items.Add("u");
				listBox.Items.Add("th");
				listBox.SelectedIndex = 0;
				listBox.Visible = false;
				_ = null;
				codeListbox.MouseClick += codeClick;
				Panel92.Controls.Add(codeListbox);
				Panel92.Controls.SetChildIndex(codeListbox, 0);
			}
			switch (e.KeyCode)
			{
			case Keys.Return:
			{
				string text2 = "<br>";
				object objectValue2 = RuntimeHelpers.GetObjectValue(NewLateBinding.LateGet(sender, null, "SelectionStart", new object[0], null, null, null));
				object[] array5 = new object[1];
				object instance = NewLateBinding.LateGet(sender, null, "Text", new object[0], null, null, null);
				object[] obj4 = new object[2] { objectValue2, text2 };
				array2 = obj4;
				bool[] obj5 = new bool[2] { true, true };
				array3 = obj5;
				object obj6 = NewLateBinding.LateGet(instance, null, "Insert", obj4, null, null, obj5);
				if (array3[0])
				{
					objectValue2 = RuntimeHelpers.GetObjectValue(array2[0]);
				}
				if (array3[1])
				{
					text2 = (string)Conversions.ChangeType(RuntimeHelpers.GetObjectValue(array2[1]), typeof(string));
				}
				array5[0] = obj6;
				NewLateBinding.LateSet(sender, null, "Text", array5, null, null);
				NewLateBinding.LateSet(sender, null, "SelectionStart", new object[1] { Operators.AddObject(objectValue2, text2.Length) }, null, null);
				codeListbox.Hide();
				return;
			}
			case Keys.Oemcomma:
				findStr = null;
				codeListbox.Location = location;
				codeListbox.Show();
				codeListbox.Location = location;
				return;
			case Keys.OemPeriod:
				codeListbox.Hide();
				return;
			case Keys.Tab:
				e.SuppressKeyPress = true;
				if (codeListbox.Visible)
				{
					string text = codeListbox.SelectedItem.ToString().ToLower();
					try
					{
						text = codeListbox.SelectedItem.ToString().Substring(codeListbox.SelectedItem.ToString().IndexOf(findStr.ToLower()) + findStr.Length);
					}
					catch (Exception ex5)
					{
						ProjectData.SetProjectError(ex5);
						Exception ex6 = ex5;
						ProjectData.ClearProjectError();
					}
					object objectValue = RuntimeHelpers.GetObjectValue(NewLateBinding.LateGet(sender, null, "SelectionStart", new object[0], null, null, null));
					object[] array4 = new object[1];
					object obj3 = NewLateBinding.LateGet(NewLateBinding.LateGet(sender, null, "Text", new object[0], null, null, null), null, "Insert", array2 = new object[2] { objectValue, text }, null, null, array3 = new bool[2] { true, true });
					if (array3[0])
					{
						objectValue = RuntimeHelpers.GetObjectValue(array2[0]);
					}
					if (array3[1])
					{
						text = (string)Conversions.ChangeType(RuntimeHelpers.GetObjectValue(array2[1]), typeof(string));
					}
					array4[0] = obj3;
					NewLateBinding.LateSet(sender, null, "Text", array4, null, null);
					NewLateBinding.LateSet(sender, null, "SelectionStart", new object[1] { Operators.AddObject(objectValue, text.Length) }, null, null);
					codeListbox.Hide();
					NewLateBinding.LateCall(sender, null, "Focus", new object[0], null, null, null, IgnoreReturn: true);
				}
				return;
			case Keys.Space:
				codeListbox.Hide();
				return;
			case Keys.Left:
				if (codeListbox.Visible)
				{
					e.SuppressKeyPress = true;
					try
					{
						codeListbox.SelectedIndex--;
						return;
					}
					catch (Exception ex11)
					{
						ProjectData.SetProjectError(ex11);
						Exception ex12 = ex11;
						ProjectData.ClearProjectError();
						return;
					}
				}
				return;
			case Keys.Up:
				if (codeListbox.Visible)
				{
					e.SuppressKeyPress = true;
					try
					{
						codeListbox.SelectedIndex--;
						return;
					}
					catch (Exception ex9)
					{
						ProjectData.SetProjectError(ex9);
						Exception ex10 = ex9;
						ProjectData.ClearProjectError();
						return;
					}
				}
				return;
			case Keys.Right:
				if (codeListbox.Visible)
				{
					e.SuppressKeyPress = true;
					try
					{
						codeListbox.SelectedIndex++;
						return;
					}
					catch (Exception ex7)
					{
						ProjectData.SetProjectError(ex7);
						Exception ex8 = ex7;
						ProjectData.ClearProjectError();
						return;
					}
				}
				return;
			case Keys.Down:
				if (codeListbox.Visible)
				{
					e.SuppressKeyPress = true;
					try
					{
						codeListbox.SelectedIndex++;
						return;
					}
					catch (Exception ex3)
					{
						ProjectData.SetProjectError(ex3);
						Exception ex4 = ex3;
						ProjectData.ClearProjectError();
						return;
					}
				}
				return;
			case Keys.Back:
				try
				{
					findStr = findStr.Remove(findStr.Length - 1);
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception ex2 = ex;
					findStr = null;
					ProjectData.ClearProjectError();
				}
				codeListbox.Location = location;
				return;
			case Keys.LShiftKey:
			case Keys.ProcessKey:
				return;
			}
			codeListbox.Location = location;
			findStr += Conversions.ToString(Strings.ChrW(unchecked((int)e.KeyCode)));
			int num = codeListbox.Items.Count - 1;
			for (int i = 0; i <= num; i++)
			{
				if (codeListbox.Items[i].ToString().StartsWith(findStr.ToLower()))
				{
					codeListbox.SelectedIndex = i;
					break;
				}
			}
		}
	}

