	{
		if (e.KeyCode == Keys.Tab)
		{
			e.IsInputKey = true;
		}
	}

	public void getKeypointXML()
	{
		ComboBox6.Items.Clear();
		ListBox7.Items.Clear();
		sjka_cyber.KeypointXML = new List<KeypointXML>();
		foreach (Keypoint item in sjka_cyber.KeypointDB)
		{
			if (Conversion.Val(item.getGroup()) == 0.0)
			{
				sjka_cyber.KeypointXML.Add(new KeypointXML(Conversions.ToString(item.getIndex()), item.getName(), item.getXML(), checked((int)Math.Round(Conversion.Val(item.getGroup())))));
				ComboBox6.Items.Add(item.getIndex().ToString("(P0####) ") + item.getName());
				ListBox7.Items.Add(item.getIndex().ToString("(P0####) ") + item.getName());
			}
		}
	}

