	private void Button47_Click(object sender, EventArgs e)
	{
		if (ComboBox6.SelectedIndex < 0)
		{
			return;
		}
		string text = "<doc>";
		checked
		{
			int num = NowKeypointXML.Count() - 1;
			for (int i = 0; i <= num; i++)
			{
				List<string> list = (List<string>)NowKeypointXML.getString(i);
				if (Operators.CompareString(list[0], "", TextCompare: false) == 0)
				{
					continue;
				}
				text = text + "\r\n    <item name=\"" + list[0].Trim() + "\">";
				int num2 = list.Count - 1;
				for (int j = 1; j <= num2; j++)
				{
					if (Operators.CompareString(list[j], "", TextCompare: false) != 0)
					{
						text = text + "\r\n        <child name=\"" + list[j].Trim() + "\" />";
					}
				}
				text += "\r\n   </item>";
