			text += "\r\n</doc>";
			string text2 = Convert.ToBase64String(Encoding.UTF8.GetBytes(text));
			if (Operators.CompareString(new GetHtmlClass(Module1._dburl + "/set.php?t=modKeypoint", "p=" + MySettingsProperty.Settings.pw + "&nm=" + TextBox10.Text + "&xml=" + text2.Replace("+", "＋") + "&n=" + Conversions.ToString(Conversion.Val(ComboBox6.Text.Substring(0, ComboBox6.Text.IndexOf(" ") - 1).Remove(0, 2))) + "&g=0", progress: true).getHTML(MyProject.Forms.mlas).Trim(), "correct", TextCompare: false) != 0)
