	public void getKeypointZip()
	{
		string hTML = new GetHtmlClass(Module1._dburl + "/get.php?t=getKeypointZip", null, progress: true).getHTML(MyProject.Forms.mlas);
		if (Operators.CompareString(hTML, "incorrect", TextCompare: false) == 0)
		{
			CustomMsgBox.CMsgBox("잠시 후에 다시 시도하십시오.\r\n이런 현상이 계속되면 MLAS를 종료하고 재시작 하십시오.", "통신대기 발생", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error, custom_msgbox.ShowLocation.BottomRight, autoClose: true, 3000);
			return;
		}
		TextBox20.Text = null;
		ListBox8.Items.Clear();
		sjka_cyber.keypointZip = hTML.Split(new string[1] { "||" }, StringSplitOptions.RemoveEmptyEntries);
		ComboBox7.Items.Clear();
		string[] keypointZip = sjka_cyber.keypointZip;
		for (int i = 0; i < keypointZip.Length; i = checked(i + 1))
		{
