	private void Button59_Click(object sender, EventArgs e)
	{
		if (Operators.CompareString(ComboBox7.Text, null, TextCompare: false) == 0)
		{
			return;
		}
		nowkeypoint_index = ComboBox7.SelectedIndex;
		checked
		{
			int num = (int)Math.Round(Conversion.Val(ComboBox7.Text.Substring(0, ComboBox7.Text.IndexOf(" ") - 1).Remove(0, 2)));
			string text = null;
			IEnumerator enumerator = default(IEnumerator);
			try
			{
				enumerator = ListBox8.Items.GetEnumerator();
				while (enumerator.MoveNext())
				{
					object objectValue = RuntimeHelpers.GetObjectValue(enumerator.Current);
					text = text + Conversions.ToString(Conversion.Val(RuntimeHelpers.GetObjectValue(NewLateBinding.LateGet(NewLateBinding.LateGet(objectValue, null, "Substring", new object[2]
					{
						0,
						Operators.SubtractObject(NewLateBinding.LateGet(objectValue, null, "IndexOf", new object[1] { " " }, null, null, null), 1)
					}, null, null, null), null, "Remove", new object[2] { 0, 2 }, null, null, null)))) + ",";
				}
			}
			finally
			{
				if (enumerator is IDisposable)
				{
					(enumerator as IDisposable).Dispose();
				}
			}
			if (Operators.CompareString(text, null, TextCompare: false) != 0)
			{
				text = text.Remove(text.Length - 1, 1);
			}
			if (Operators.CompareString(new GetHtmlClass(Module1._dburl + "/set.php?t=modKeypointZip", "p=" + MySettingsProperty.Settings.pw + "&nm=" + Module1.UrlEncode(TextBox20.Text.Trim()) + "&n=" + Conversions.ToString(num) + "&d=" + Module1.UrlEncode(text), progress: true).getHTML(MyProject.Forms.mlas).Trim(), "incorrect", TextCompare: false) == 0)
			{
				CustomMsgBox.CMsgBox("저장에 실패했습니다.\r\n인터넷 또는 서버의 상태를 점검하십시오.", "통신 오류!", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
				return;
