	private void Button70_Click(object sender, EventArgs e)
	{
		if (Operators.CompareString(ComboBox9.Text, null, TextCompare: false) == 0)
		{
			return;
		}
		nowkeypoint_index = ComboBox9.SelectedIndex;
		checked
		{
			int num = (int)Math.Round(Conversion.Val(ComboBox9.Text.Substring(0, ComboBox9.Text.IndexOf(" ") - 1).Remove(0, 2)));
			string text = null;
			IEnumerator enumerator = default(IEnumerator);
			try
			{
				enumerator = ListBox10.Items.GetEnumerator();
				while (enumerator.MoveNext())
				{
					object objectValue = RuntimeHelpers.GetObjectValue(enumerator.Current);
					text = text + Conversions.ToString(Conversion.Val(RuntimeHelpers.GetObjectValue(NewLateBinding.LateGet(NewLateBinding.LateGet(objectValue, null, "Substring", new object[2]
					{
						0,
						Operators.SubtractObject(NewLateBinding.LateGet(objectValue, null, "IndexOf", new object[1] { " " }, null, null, null), 1)
					}, null, null, null), null, "Remove", new object[2] { 0, 2 }, null, null, null)))) + ",";
				}
			}
			finally
			{
				if (enumerator is IDisposable)
				{
					(enumerator as IDisposable).Dispose();
				}
			}
			if (Operators.CompareString(text, null, TextCompare: false) != 0)
			{
				text = text.Remove(text.Length - 1, 1);
			}
			if (Operators.CompareString(new GetHtmlClass(Module1._dburl + "/set.php?t=modKWZip", "p=" + MySettingsProperty.Settings.pw + "&nm=" + Module1.UrlEncode(TextBox22.Text.Trim()) + "&n=" + Conversions.ToString(num) + "&d=" + Module1.UrlEncode(text)).getHTML(MyProject.Forms.mlas).Trim(), "incorrect", TextCompare: false) == 0)
			{
				CustomMsgBox.CMsgBox("서버에 데이터를 저장하지 못했습니다.\r\n인터넷 또는 서버의 상태를 점검하십시오.", "통신 오류!", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
				return;
			}
			CustomMsgBox.CMsgBox("서버에 성공적으로 저장 하였습니다.", "저장 완료", "닫기", custom_msgbox.CMsgboxColor.DarkGreen, custom_msgbox.CmsgBoxIcon.icon_Information, custom_msgbox.ShowLocation.BottomRight, autoClose: true, 1500);
			getKZip2();
			try
			{
				ComboBox9.SelectedIndex = nowkeypoint_index;
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ProjectData.ClearProjectError();
			}
		}
	}

