	public void getAccount()
	{
		sjka_cyber.ACCOUNT_AD = new List<AccountData>();
		string hTML = new GetHtmlClass(Module1._dburl + "/set.php?t=getAccount", "p=" + MySettingsProperty.Settings.pw, progress: true).getHTML(MyProject.Forms.mlas);
		if (Operators.CompareString(hTML, "incorrect", TextCompare: false) == 0)
		{
			CustomMsgBox.CMsgBox("잠시 후에 다시 시도하십시오.\r\n이런 현상이 계속되면 MLAS를 종료하고 재시작 하십시오.", "통신대기 발생", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error, custom_msgbox.ShowLocation.BottomRight, autoClose: true, 3000);
			return;
		}
		string[] array = hTML.Split(new string[1] { "|" }, StringSplitOptions.RemoveEmptyEntries);
		ListView listView = ListView2;
		listView.Columns[0].Text = "번호";
		listView.Columns[1].Text = "계정 ID";
		listView.Columns[2].Text = "영구 강좌";
		listView.Columns[3].Text = "상태";
		listView.Columns[4].Text = "연동된 날짜";
		listView.Columns[5].Text = "번호 확인";
		listView.Columns[6].Text = "기간제 강좌";
		listView.ListViewItemSorter = new ListViewComparer(0, SortOrder.Ascending);
		listView.Sort();
		listView.Items.Clear();
		_ = null;
		acc_num.Text = null;
		acc_id.Text = null;
		acc_cource.Text = null;
		acc_status.Text = null;
		acc_phone_c.Checked = false;
		acc_allowdate.Text = null;
		TextBox39.Value = 0m;
		ListBox15.Items.Clear();
		ListBox17.Items.Clear();
		DateTimePicker1.Enabled = false;
		int num = 0;
		string[] array2 = array;
		checked
		{
			for (int i = 0; i < array2.Length; i++)
			{
				string[] array3 = array2[i].Split(new string[1] { "$" }, StringSplitOptions.None);
				ListView2.Items.Add(array3[0]);
				int num2 = 1;
				do
				{
					switch (num2)
					{
					case 3:
						if (Operators.CompareString(array3[3], "1", TextCompare: false) == 0)
						{
							ListView2.Items[num].SubItems.Add("이용가능");
						}
						else
						{
							ListView2.Items[num].SubItems.Add("탈퇴");
						}
						break;
					case 5:
						if (Operators.CompareString(array3[5], "1", TextCompare: false) == 0)
						{
							ListView2.Items[num].SubItems.Add("번호 확인함");
						}
						else
						{
							ListView2.Items[num].SubItems.Add("건너뜀");
						}
						break;
					default:
						if (Operators.CompareString(array3[num2], "", TextCompare: false) == 0)
						{
							ListView2.Items[num].SubItems.Add("NULL");
						}
						else
						{
							ListView2.Items[num].SubItems.Add(array3[num2]);
						}
						break;
					}
					num2++;
				}
				while (num2 <= 5);
				if (Operators.CompareString(array3[7], null, TextCompare: false) == 0)
				{
					ListView2.Items[num].SubItems.Add("NULL");
				}
				else
				{
					ListView2.Items[num].SubItems.Add("있음");
				}
				sjka_cyber.ACCOUNT_AD.Add(new AccountData(array3[0], array3[1], array3[2], array3[3], array3[4], array3[5], array3[7]));
				num++;
			}
		}
	}

	private void ListView2_SelectedIndexChanged(object sender, EventArgs e)
