	private bool getDetail(string imgNumber)
	{
		try
		{
			string text = null;
			try
			{
				text = new GetHtmlClass(Module1._dburl + "/get.php?t=imgBlobD&n=" + imgNumber.Trim()).getHTML(MyProject.Forms.mlas).Trim();
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ProjectData.ClearProjectError();
			}
			if (text == null)
			{
				return false;
			}
			byte[] buffer = Convert.FromBase64String(text);
			MemoryStream stream = new MemoryStream(buffer);
			PictureBox27.Image = Image.FromStream(stream);
			return true;
		}
		catch (Exception ex3)
		{
			ProjectData.SetProjectError(ex3);
			Exception ex4 = ex3;
			Console.WriteLine(ex4.Message);
			GC.Collect();
			PictureBox27.Image = null;
			ProjectData.ClearProjectError();
		}
		return false;
	}

	public void tag_id_KeyUp(object sender, KeyEventArgs e)
