			if (Operators.CompareString(tag_height.Text, null, TextCompare: false) != 0)
			{
				obj = Operators.ConcatenateObject(obj, " height=" + tag_height.Text);
			}
			if (Operators.CompareString(tag_caption.Text, null, TextCompare: false) != 0)
			{
				obj = Operators.ConcatenateObject(obj, " caption=\"" + tag_caption.Text + "\"");
			}
			imgObject.Text = imgObject.Text.Replace(imgObject.Text.Substring(Conversions.ToInteger(value), imgObject.Text.Substring(Conversions.ToInteger(value)).IndexOf(">")), Conversions.ToString(obj));
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
	}

