	public void InitKeypoint()
	{
		ComboBox11.Items.Clear();
		ComboBox12.Items.Clear();
		sjka_cyber.KeypointDB = new List<Keypoint>();
		TextBox32.Text = null;
		TextBox29.Text = "<font color=blue>Hello World</font>";
		string hTML = new GetHtmlClass(Module1._dburl + "/get.php?t=getKPTList", Conversions.ToString(Value: true)).getHTML(MyProject.Forms.mlas);
		if (Operators.CompareString(hTML, "incorrect", TextCompare: false) == 0)
		{
			CustomMsgBox.CMsgBox("잠시 후에 다시 시도하십시오.\r\n이런 현상이 계속되면 MLAS를 종료하고 재시작 하십시오.", "통신대기 발생", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error, custom_msgbox.ShowLocation.BottomRight, autoClose: true, 3000);
			return;
		}
		string[] array = hTML.Split(new string[1] { "||" }, StringSplitOptions.RemoveEmptyEntries);
		for (int i = 0; i < array.Length; i = checked(i + 1))
		{
			string[] array2 = array[i].Split(new string[1] { "**" }, StringSplitOptions.None);
			sjka_cyber.KeypointDB.Add(new Keypoint(array2[0], array2[1], null, array2[2]));
			if (Conversion.Val(array2[2]) != 0.0)
			{
				foreach (Keypoint item3 in sjka_cyber.KeypointDB)
				{
					bool flag = false;
					if ((double)item3.getIndex() == Conversion.Val(array2[2]))
					{
						string item = Conversion.Val(array2[0]).ToString("(M0####) ") + " [" + item3.getName() + "] " + array2[1];
						ComboBox11.Items.Add(item);
						flag = true;
						break;
					}
					if (!flag)
					{
						string item2 = Conversion.Val(array2[0]).ToString("(M0####) ") + array2[1];
						ComboBox11.Items.Add(item2);
						break;
					}
				}
			}
			else
			{
				ComboBox12.Items.Add(Conversion.Val(array2[0]).ToString("(P0####) ") + array2[1]);
			}
		}
	}

