					panel = null;
					button.MouseDown += closeform2;
					p4.Controls.Add(pn);
					p4.Controls.SetChildIndex(pn, 0);
					ProjectData.ClearProjectError();
					return;
				}
			}
			if (NewLateBinding.LateGet(sender, null, "Image", new object[0], null, null, null) == null)
