				return;
			}
			SaveFileDialog saveFileDialog = new SaveFileDialog();
			SaveFileDialog saveFileDialog2 = saveFileDialog;
			saveFileDialog2.FileName = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(TextBox11.Text + "_", NewLateBinding.LateGet(sender, null, "name", new object[0], null, null, null)), "."), Module1.GetImageExtension(pictureBox.Image)));
