	private void Button4_Click(object sender, EventArgs e)
	{
		checked
		{
			DocData docData = sjka_cyber.docs.Find((DocData a) => ((double)a.Index == Conversion.Val(ComboBox2.SelectedItem.ToString().Substring(2, ComboBox2.SelectedItem.ToString().IndexOf(")") - 1))) ? true : false);
			int num = 0;
			string[] array = TextBox1.Text.Split(new string[1] { "/" }, StringSplitOptions.None);
			string[] array2 = array;
			foreach (string text in array2)
			{
				if (num > docData.Count() - 1)
				{
					docData.AddSubject(text);
					ComboBox1.Items.Add(Conversions.ToString(num + 1) + " 과목 [" + text + "]");
				}
				else
				{
					docData.SubjectItems(num).setName(text);
					ComboBox1.Items[num] = Conversions.ToString(num + 1) + " 과목 [" + text + "]";
				}
				if (array.Length < docData.Count())
				{
					docData.RemoveAt(docData.Count() - 1);
					ComboBox1.Items.RemoveAt(docData.Count() - 1);
				}
				num++;
			}
		}
	}

