	private void Button120_Click(object sender, EventArgs e)
	{
		string text = null;
		OpenFileDialog openFileDialog = new OpenFileDialog();
		openFileDialog.FileName = "*.csv";
		openFileDialog.Filter = "엑셀 데이터 CSV(*.csv)|*.csv|도큐멘트 파일(*.sjkadoc)|*.sjkadoc";
		openFileDialog.Title = "불러올 백업 파일을 선택하십시오.";
		if (openFileDialog.ShowDialog() == DialogResult.Cancel)
		{
			return;
		}
		backupmode = true;
		string text2 = null;
		string name = null;
		string text3 = null;
		string value = null;
		string text4 = null;
		checked
		{
			try
			{
				using StreamReader streamReader = new StreamReader(openFileDialog.FileName, Encoding.Default);
				text2 = streamReader.ReadLine().Replace(",", "").Trim();
				switch (text2)
				{
				case "<sjkadoc>":
					CustomMsgBox.CMsgBox("지원하지 않는 파일입니다.", "파일 열기 실패", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
					return;
				case "<sjkadoc2>":
					name = streamReader.ReadLine();
					text3 = streamReader.ReadLine();
					value = streamReader.ReadLine();
					text = streamReader.ReadToEnd();
					break;
				case "<excel1>":
				{
					if (MessageBox.Show("이전 버전에서 만들어진 파일입니다. 호환성 문제로 파일이 올바르게 표시되지 않을 수 있습니다.\r\n\r\n파일을 여시겠습니까?", "알림", MessageBoxButtons.YesNo, MessageBoxIcon.Exclamation) == DialogResult.No)
					{
						return;
					}
					string[] array3 = streamReader.ReadLine().Split(new string[1] { "," }, StringSplitOptions.None);
					name = array3[0];
					text3 = array3[1];
					value = Conversions.ToString(0);
					text = streamReader.ReadLine();
					text = streamReader.ReadToEnd();
					string[] array4 = MarkFindReplace(text).Replace("1과목", "<subject>").Replace("2과목", "<subject>").Replace("3과목", "<subject>")
						.Replace("4과목", "<subject>")
						.Replace("5과목", "<subject>")
						.Replace("6과목", "<subject>")
						.Replace("7과목", "<subject>")
						.Replace("8과목", "<subject>")
						.Split(new string[1] { "\r\n" }, StringSplitOptions.RemoveEmptyEntries);
					foreach (string text7 in array4)
					{
						if (Operators.CompareString(text7.Replace(",", "").Trim(), "<subject>", TextCompare: false) == 0)
						{
							text4 = text4 + text7.Replace(",", "").Trim() + "\r\n";
							continue;
						}
						text4 += "<question>\r\n";
						string[] array5 = text7.Split(new string[1] { "," }, StringSplitOptions.None);
						int num = array5.Length - 1;
						for (int l = 0; l <= num; l++)
						{
							if (l == 2)
							{
								l++;
								continue;
							}
							unchecked
							{
								if (Operators.CompareString(array5[l], null, TextCompare: false) == 0 && l != 9)
								{
									text4 += "null\r\n";
									continue;
								}
								if (l < 3)
								{
									text4 = text4 + array5[l].Replace("<comma>", ",") + "\r\n";
								}
								if (l != 3)
								{
									if (l > 3 && l != 9)
									{
										text4 = text4 + array5[l].Replace("<comma>", ",") + "\r\n";
									}
									if (l == 9)
									{
										text4 = ((Operators.CompareString(array5[9], null, TextCompare: false) != 0) ? (text4 + array5[9].Replace("<comma>", ",") + "\r\n") : (text4 + "null\r\n"));
										text4 = ((Operators.CompareString(array5[3], null, TextCompare: false) != 0) ? (text4 + array5[3].Replace("<comma>", ",") + "\r\n") : (text4 + "null\r\n"));
									}
								}
							}
						}
						text4 += "\r\n";
					}
					text = text4;
					break;
				}
				case "<excel2>":
				{
					name = streamReader.ReadLine().Replace(",", "").Trim();
					text3 = streamReader.ReadLine().Replace(",", "").Trim();
					value = streamReader.ReadLine().Replace(",", "").Trim();
					text = streamReader.ReadLine();
					text = streamReader.ReadLine();
					text = streamReader.ReadToEnd();
					string[] array = MarkFindReplace(text).Replace("<과목구분>", "<subject>").Split(new string[1] { "\r\n" }, StringSplitOptions.RemoveEmptyEntries);
					foreach (string text5 in array)
					{
						if (Operators.CompareString(text5.Replace(",", "").Trim(), "<subject>", TextCompare: false) == 0)
						{
							text4 = text4 + text5 + "\r\n";
							continue;
						}
						text4 += "<question>\r\n";
						string[] array2 = text5.Split(new string[1] { "," }, StringSplitOptions.None);
						foreach (string text6 in array2)
						{
							text4 = ((Operators.CompareString(text6, null, TextCompare: false) != 0) ? (text4 + text6.Replace("<comma>", ",") + "\r\n") : (text4 + "null\r\n"));
						}
						text4 += "\r\n";
					}
					text = text4;
					break;
				}
				default:
					CustomMsgBox.CMsgBox("지원하지 않는 파일입니다.", "파일 열기 실패", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
					return;
				}
			}
			catch (IOException ex)
			{
				ProjectData.SetProjectError(ex);
				IOException ex2 = ex;
				CustomMsgBox.CMsgBox("선택된 파일을 다른 프로그램이 사용 중이므로 열 수 없습니다.", "파일 열기 실패", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
				ProjectData.ClearProjectError();
				return;
			}
			if (MessageBox.Show("파일을 가져오면 작업 중인 기출문제에 덮어쓰기 합니다.\r\n한번 덮어쓴 자료는 복구할 수 없습니다.\r\n\r\n파일을 가져오시겠습니까?", "가져오기 경고", MessageBoxButtons.YesNo, MessageBoxIcon.Exclamation) == DialogResult.No)
			{
				return;
			}
			DocData docData = sjka_cyber.docs.Find((DocData a) => ((double)a.Index == Conversion.Val(ComboBox2.SelectedItem.ToString().Substring(2, ComboBox2.SelectedItem.ToString().IndexOf(")") - 1))) ? true : false);
			docData.Clear(text3.Split(new string[1] { "/" }, StringSplitOptions.None));
			docData.Name = name;
			docData.Silgi = Conversions.ToBoolean(value);
			bool flag = false;
			int num2 = 0;
			string text8 = null;
			try
			{
				int num3 = 0;
				string[] array6 = text.Trim().Split(new string[1] { "<subject>" }, StringSplitOptions.RemoveEmptyEntries);
				foreach (string obj in array6)
				{
					int num4 = 0;
					string[] array7 = obj.Trim().Split(new string[1] { "<question>" }, StringSplitOptions.RemoveEmptyEntries);
					foreach (string text9 in array7)
					{
						num4++;
						if (!docData.SubjectItems(num3).Add(text9.Trim()))
						{
							if (!text9.Trim().Equals(",,,,,,,,"))
							{
								num2++;
								text8 = text8 + "추가 실패한 문제 : " + text9.Replace("\r\n", " / ") + "\r\n";
							}
						}
						else if (!flag)
						{
							flag = true;
						}
					}
					num3++;
				}
				if (!flag)
				{
					CustomMsgBox.CMsgBox("추가 실패, 단 한 문제도 추가하지 못했습니다. 파일 형식에 오류가 있습니다.", "파일 형식 오류", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
					sjka_cyber.docs.RemoveAt(sjka_cyber.docs.Count - 1);
					ComboBox2.Items.RemoveAt(ComboBox2.Items.Count - 1);
					return;
				}
				TextBox2.Text = name;
				TextBox1.Text = null;
				ComboBox1.Items.Clear();
				int num5 = docData.Count() - 1;
				for (int num6 = 0; num6 <= num5; num6++)
				{
					ComboBox1.Items.Add(Conversions.ToString(num6 + 1) + " 과목 [" + docData.getSubjectName(num6) + "]");
					TextBox textBox;
					(textBox = TextBox1).Text = textBox.Text + docData.getSubjectName(num6) + "/";
				}
				TextBox1.Text = TextBox1.Text.Remove(TextBox1.Text.Length - 1);
				if (docData.Silgi)
				{
					RadioButton5.Checked = true;
				}
				else
				{
					RadioButton6.Checked = true;
				}
				ComboBox1.SelectedIndex = 0;
				if (num2 > 0)
				{
					CustomMsgBox.CMsgBox("불러오는데 성공했으나, 실패한 항목이 있습니다.\r\n실패한 갯수: " + num2 + "\r\n" + text8, "일부 문제가 추가되지 않았습니다.", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
				}
				else
				{
					CustomMsgBox.CMsgBox(openFileDialog.FileName.Substring(openFileDialog.FileName.LastIndexOf("\\") + 1) + " 파일을 가져오는데 성공했습니다. 검토 후 저장버튼을 누르십시오.", "가져오기 성공", "닫기", custom_msgbox.CMsgboxColor.DarkGreen, custom_msgbox.CmsgBoxIcon.icon_Exclamation, custom_msgbox.ShowLocation.BottomRight);
				}
			}
			catch (Exception ex3)
			{
				ProjectData.SetProjectError(ex3);
				Exception ex4 = ex3;
				CustomMsgBox.CMsgBox("파일을 분석하는 중에 알 수 없는 형식을 발견했습니다. 문서의 버전을 확인하십시오.\r\n문서 버전: " + text2 + "\r\n메시지: " + ex4.Message, "파일 열기 실패", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
				ProjectData.ClearProjectError();
			}
			openFileDialog = null;
		}
	}

