	private void rtbScroll()
	{
		int verticalPosition = RichTextbox1.VerticalPosition;
		IntPtr handle = RichTextbox2.Handle;
		Point lParam = new Point(0, verticalPosition);
		SendMessage(handle, 1246, 0, ref lParam);
		IntPtr handle2 = RichTextbox3.Handle;
		lParam = new Point(0, verticalPosition);
		SendMessage(handle2, 1246, 0, ref lParam);
	}

	private void Timer1_Tick(object sender, EventArgs e)
	{
		rtbBarInit();
		rtbScroll();
		Timer1.Stop();
	}

	private void rtbBarInit()
	{
		bool flag = false;
		if (rtbBarInitBusy)
		{
			return;
		}
		rtbBarInitBusy = true;
		rtbError = 0;
		RichTextBox richTextBox = new RichTextBox();
		richTextBox.Font = new Font("굴림", 9.75f);
		RichTextBox richTextBox2 = new RichTextBox();
		richTextBox2.Font = new Font("굴림", 9.75f);
		RichTextbox1.LanguageOption = RichTextBoxLanguageOptions.UIFonts;
		RichTextbox2.LanguageOption = RichTextBoxLanguageOptions.UIFonts;
		RichTextbox3.LanguageOption = RichTextBoxLanguageOptions.UIFonts;
		RichTextBox richTextBox3 = richTextBox;
		int num = 0;
		Color selectionColor = richTextBox3.SelectionColor;
		int num2 = 0;
		int num3 = 0;
		string[] lines = RichTextbox1.Lines;
		int num4 = 0;
		checked
		{
			while (true)
			{
				if (num4 < lines.Length)
				{
					string text = lines[num4];
					if (!flag & !rtbBarInitBusy)
					{
						break;
					}
					num3++;
					string left = text.Trim();
					if (Operators.CompareString(left, "<subject>", TextCompare: false) == 0)
					{
						richTextBox3.SelectionStart = richTextBox.Text.Length;
						richTextBox3.SelectionColor = Color.Yellow;
						richTextBox3.SelectionBackColor = Color.FromArgb(64, 64, 64);
						richTextBox3.BackColor = Color.FromArgb(64, 64, 64);
						richTextBox3.SelectionAlignment = HorizontalAlignment.Right;
						richTextBox3.SelectionFont = new Font("굴림", 9.75f, FontStyle.Italic);
						richTextBox3.AppendText("< 과목구분 >\r\n");
						richTextBox3.SelectionColor = selectionColor;
					}
					else if (Operators.CompareString(left, "<question>", TextCompare: false) == 0)
					{
						if (unchecked(rtbError == 0 && num2 != 0 && num2 < 999999))
						{
							rtbError = num3 - num2 - 1;
							quesErrorMsg = "문제 형식에 빠진 항목이 있습니다.";
						}
						num2 = 0;
						num++;
						richTextBox3.SelectionStart = richTextBox3.Text.Length;
						richTextBox3.SelectionColor = Color.White;
						richTextBox3.SelectionBackColor = Color.DarkGreen;
						richTextBox3.SelectionAlignment = HorizontalAlignment.Right;
						richTextBox3.SelectionFont = new Font("굴림", 9.75f, FontStyle.Italic);
						richTextBox3.AppendText("< " + num.ToString("0##") + " >\r\n");
						richTextBox3.SelectionColor = selectionColor;
					}
					else if (Operators.CompareString(left, null, TextCompare: false) == 0)
					{
						richTextBox3.SelectionStart = richTextBox3.Text.Length;
						richTextBox3.SelectionColor = Color.Orange;
						richTextBox3.SelectionAlignment = HorizontalAlignment.Right;
						richTextBox3.SelectionFont = new Font("굴림", 9.75f, FontStyle.Italic);
						richTextBox3.AppendText("\r\n");
						richTextBox3.SelectionColor = selectionColor;
						num2++;
					}
					else
					{
						switch (num2)
						{
						case 0:
							richTextBox3.SelectionStart = richTextBox3.Text.Length;
							richTextBox3.SelectionColor = Color.DarkGray;
							richTextBox3.SelectionAlignment = HorizontalAlignment.Right;
							richTextBox3.SelectionFont = new Font("굴림", 9.75f, FontStyle.Italic);
							richTextBox3.AppendText("문제\r\n");
							richTextBox3.SelectionColor = selectionColor;
							num2++;
							break;
						case 1:
							richTextBox3.SelectionStart = richTextBox3.Text.Length;
							richTextBox3.SelectionColor = Color.DarkGray;
							richTextBox3.SelectionAlignment = HorizontalAlignment.Right;
							richTextBox3.SelectionFont = new Font("굴림", 9.75f, FontStyle.Italic);
							richTextBox3.AppendText("텍스트\r\n");
							richTextBox3.SelectionColor = selectionColor;
							num2++;
							break;
						case 2:
							richTextBox3.SelectionStart = richTextBox3.Text.Length;
							richTextBox3.SelectionColor = Color.DarkGray;
							richTextBox3.SelectionAlignment = HorizontalAlignment.Right;
							richTextBox3.SelectionFont = new Font("굴림", 9.75f, FontStyle.Italic);
							richTextBox3.AppendText("보기1\r\n");
							richTextBox3.SelectionColor = selectionColor;
							num2++;
							break;
						case 3:
							richTextBox3.SelectionStart = richTextBox3.Text.Length;
							richTextBox3.SelectionColor = Color.DarkGray;
							richTextBox3.SelectionAlignment = HorizontalAlignment.Right;
							richTextBox3.SelectionFont = new Font("굴림", 9.75f, FontStyle.Italic);
							richTextBox3.AppendText("보기2\r\n");
							richTextBox3.SelectionColor = selectionColor;
							num2++;
							break;
						case 4:
							richTextBox3.SelectionStart = richTextBox3.Text.Length;
							richTextBox3.SelectionColor = Color.DarkGray;
							richTextBox3.SelectionAlignment = HorizontalAlignment.Right;
							richTextBox3.SelectionFont = new Font("굴림", 9.75f, FontStyle.Italic);
							richTextBox3.AppendText("보기3\r\n");
							richTextBox3.SelectionColor = selectionColor;
							num2++;
							break;
						case 5:
							richTextBox3.SelectionStart = richTextBox3.Text.Length;
							richTextBox3.SelectionColor = Color.DarkGray;
							richTextBox3.SelectionAlignment = HorizontalAlignment.Right;
							richTextBox3.SelectionFont = new Font("굴림", 9.75f, FontStyle.Italic);
							richTextBox3.AppendText("보기4\r\n");
							richTextBox3.SelectionColor = selectionColor;
							num2++;
							break;
						case 6:
							richTextBox3.SelectionStart = richTextBox3.Text.Length;
							richTextBox3.SelectionColor = Color.DarkGray;
							richTextBox3.SelectionAlignment = HorizontalAlignment.Right;
							richTextBox3.SelectionFont = new Font("굴림", 9.75f, FontStyle.Italic);
							richTextBox3.AppendText("보기5\r\n");
							richTextBox3.SelectionColor = selectionColor;
							num2++;
							break;
						case 7:
							richTextBox3.SelectionStart = richTextBox3.Text.Length;
							richTextBox3.SelectionColor = Color.DarkGray;
							richTextBox3.SelectionAlignment = HorizontalAlignment.Right;
							richTextBox3.SelectionFont = new Font("굴림", 9.75f, FontStyle.Italic);
							richTextBox3.AppendText("정답\r\n");
							richTextBox3.SelectionColor = selectionColor;
							num2++;
							break;
						case 8:
							richTextBox3.SelectionStart = richTextBox3.Text.Length;
							richTextBox3.SelectionColor = Color.DarkGray;
							richTextBox3.SelectionAlignment = HorizontalAlignment.Right;
							richTextBox3.SelectionFont = new Font("굴림", 9.75f, FontStyle.Italic);
							richTextBox3.AppendText("해설\r\n");
							richTextBox3.SelectionColor = selectionColor;
							num2 = 999999;
							break;
						default:
							richTextBox3.SelectionStart = richTextBox3.Text.Length;
							richTextBox3.SelectionColor = Color.Red;
							richTextBox3.SelectionAlignment = HorizontalAlignment.Right;
							richTextBox3.SelectionFont = new Font("굴림", 9.75f, FontStyle.Italic);
							richTextBox3.AppendText("잘못된 열\r\n");
							richTextBox3.SelectionColor = selectionColor;
							num2++;
							if (rtbError == 0)
							{
								rtbError = num3;
								quesErrorMsg = "잘못된 열이 있습니다.";
							}
							break;
						}
					}
					richTextBox2.SelectionStart = richTextBox2.Text.Length;
					richTextBox2.SelectionColor = Color.Navy;
					richTextBox2.SelectionAlignment = HorizontalAlignment.Center;
					richTextBox2.SelectionFont = new Font("굴림", 9.75f);
					richTextBox2.AppendText(Conversions.ToString(num3) + "\r\n");
					richTextBox2.SelectionColor = selectionColor;
					Application.DoEvents();
					num4++;
					continue;
				}
				try
				{
					if (unchecked(RichTextbox1.Text.Substring(RichTextbox1.Text.LastIndexOf("<question>")).Split(new string[2] { "\r\n", "\n" }, StringSplitOptions.None).Length < 10 && rtbError == 0 && num2 != 0 && num2 < 999999))
					{
						rtbError = num3 - num2;
						quesErrorMsg = "문제 형식에 빠진 항목이 있습니다.";
					}
				}
				catch (Exception ex)
				{
					ProjectData.SetProjectError(ex);
					Exception ex2 = ex;
					ProjectData.ClearProjectError();
				}
				richTextBox3 = null;
				RichTextbox2.Rtf = richTextBox.Rtf;
				RichTextbox3.Rtf = richTextBox2.Rtf;
				rtbBarInitBusy = false;
				break;
			}
		}
	}

	private void TabControl2_SelectedIndexChanged(object sender, EventArgs e)
	{
		int selectedIndex = TabControl2.SelectedIndex;
		if (selectedIndex == 0 || selectedIndex != 1)
		{
			return;
		}
		checked
		{
			DocData docData = sjka_cyber.docs.Find((DocData a) => ((double)a.Index == Conversion.Val(ComboBox2.SelectedItem.ToString().Substring(2, ComboBox2.SelectedItem.ToString().IndexOf(")") - 1))) ? true : false);
			string text = null;
			foreach (DocData.SubjectData item in docData.SubjectItems())
			{
				text += "<subject>\r\n";
				int num = item.Count() - 1;
				for (int i = 0; i <= num; i++)
