	private void Button127_Click(object sender, EventArgs e)
	{
		if (rtbError != 0)
		{
			CustomMsgBox.CMsgBox(quesErrorMsg + "\r\n<오류 발생 열: " + Conversions.ToString(rtbError) + ">", "무결성 검사(Validation Check)", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
			return;
		}
		if (TextBox1.Text.Split(new string[1] { "/" }, StringSplitOptions.None).Length < RichTextbox1.Text.Split(new string[1] { "<subject>" }, StringSplitOptions.RemoveEmptyEntries).Length)
		{
			CustomMsgBox.CMsgBox("<subject> 수와 과목별 이름의 개수가 일치하지 않습니다.", "무결성 검사(Validation Check)", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
			return;
		}
		checked
		{
			DocData docData = sjka_cyber.docs.Find((DocData a) => ((double)a.Index == Conversion.Val(ComboBox2.SelectedItem.ToString().Substring(2, ComboBox2.SelectedItem.ToString().IndexOf(")") - 1))) ? true : false);
			docData.Clear(TextBox1.Text.Split(new string[1] { "/" }, StringSplitOptions.None));
			docData.Name = TextBox2.Text;
			docData.Silgi = RadioButton5.Checked;
			bool flag = false;
			int num = 0;
			string text = null;
			int num2 = 0;
			string[] array = RichTextbox1.Text.Trim().Split(new string[1] { "<subject>" }, StringSplitOptions.RemoveEmptyEntries);
			foreach (string obj in array)
			{
				int num3 = 0;
				string[] array2 = obj.Trim().Split(new string[1] { "<question>" }, StringSplitOptions.RemoveEmptyEntries);
				foreach (string text2 in array2)
				{
					num3++;
					if (!docData.SubjectItems(num2).Add(text2.Trim()))
					{
						if (!text2.Trim().Equals(",,,,,,,,"))
						{
							num++;
							text = "추가 실패한 문제 : " + text2.Replace("\r\n", " / ") + "\r\n";
						}
					}
					else if (!flag)
					{
						flag = true;
					}
				}
				num2++;
			}
			if (!flag)
			{
				CustomMsgBox.CMsgBox("추가 실패, 단 한 문제도 추가하지 못했습니다. 파일 형식에 오류가 있습니다.", "파일 형식 오류", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
				sjka_cyber.docs.RemoveAt(sjka_cyber.docs.Count - 1);
				ComboBox2.Items.RemoveAt(ComboBox2.Items.Count - 1);
				return;
			}
			ComboBox1.Items.Clear();
			int num4 = docData.Count() - 1;
			for (int k = 0; k <= num4; k++)
			{
				ComboBox1.Items.Add(Conversions.ToString(k + 1) + " 과목 [" + docData.getSubjectName(k) + "]");
			}
			ComboBox1.SelectedIndex = 0;
			if (num > 0)
			{
				CustomMsgBox.CMsgBox("잘못된 형식이 있습니다.\r\n자세히 보려면 스크롤을 내리세요.: " + num + "\r\n" + text, "일부 문제가 추가되지 않았습니다.", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
			}
			else
			{
				Button127.BackgroundImage = Resources.public_button_close;
			}
		}
	}

