		{
			enumerator = ListView3.SelectedItems.GetEnumerator();
			while (enumerator.MoveNext())
			{
				ListViewItem listViewItem = (ListViewItem)enumerator.Current;
				if (new GetHtmlClass(Module1._dburl + "/set.php?t=updateFeedBack", "p=" + MySettingsProperty.Settings.pw + "&n=" + listViewItem.SubItems[1].Text, progress: true).getHTML(MyProject.Forms.mlas).Contains("incorrect"))
				{
					CustomMsgBox.CMsgBox("업데이트에 실패했습니다.\r\n인터넷 또는 서버의 상태를 점검하십시오.", "통신 오류!", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
					NewLateBinding.LateSet(sender, null, "Enabled", new object[1] { true }, null, null);
					NewLateBinding.LateSet(sender, null, "checked", new object[1] { false }, null, null);
					continue;
				}
				foreach (sjkaCyberFeedback item in sjka_cyber.feedback)
				{
					if ((double)item.getNum() == Conversion.Val(listViewItem.SubItems[1].Text))
