	private void CheckBox11_CheckedChanged(object sender, EventArgs e)
	{
		if (CheckBox11.Checked)
		{
			if (!Information.IsNothing(sjka_cyber.emulator))
			{
				sjka_cyber.emulator.Show();
			}
			else
			{
				sjka_cyber.emulator = new Form();
				Form emulator = sjka_cyber.emulator;
				emulator.Size = new Size(388, 804);
				emulator.FormBorderStyle = FormBorderStyle.None;
				emulator.Controls.Add(diag_emulator);
				emulator.MaximizeBox = false;
				emulator.ShowIcon = false;
				emulator.TopMost = true;
				emulator.Text = "Simulator";
				emulator.TransparencyKey = Color.FromArgb(255, 0, 255);
				sjka_cyber.emulator.FormClosing += emulator_FormClosing;
				sjka_cyber.emulator.Load += delegate(object a0, EventArgs a1)
				{
					emulator_Load((Form)a0, a1);
				};
				emulator.Show();
				diag_emulator.Dock = DockStyle.Fill;
				_ = null;
			}
			try
			{
				DocData emulator2 = sjka_cyber.docs.Find((DocData a) => ((double)a.Index == Conversion.Val(ComboBox2.SelectedItem.ToString().Substring(2, checked(ComboBox2.SelectedItem.ToString().IndexOf(")") - 1)))) ? true : false);
				setEmulator(emulator2);
				return;
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				sjka_cyber.emulator.Hide();
				ProjectData.ClearProjectError();
				return;
			}
		}
		sjka_cyber.emulator.Hide();
	}

