	private void Button150_Click_1(object sender, EventArgs e)
	{
		if (ComboBox5.SelectedIndex < 0)
		{
			return;
		}
		string text = null;
		ListBox14.Items.Add(ComboBox5.SelectedItem.ToString());
		try
		{
			text = Conversions.ToString(Conversion.Val(ComboBox5.Text.Substring(0, checked(ComboBox5.Text.IndexOf(" ") - 1)).Remove(0, 2)));
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
		if (Operators.CompareString(text, null, TextCompare: false) != 0)
		{
			if (TextBox4.Text.EndsWith(","))
			{
				TextBox4.Text += text;
			}
			else if (Operators.CompareString(TextBox4.Text, null, TextCompare: false) == 0)
			{
				TextBox4.Text = text;
			}
			else
			{
				TextBox textBox;
				(textBox = TextBox4).Text = textBox.Text + "," + text;
			}
		}
	}

	private void Button151_Click(object sender, EventArgs e)
	{
		if (ListBox14.SelectedIndex < 0)
		{
			return;
		}
		int selectedIndex = ListBox14.SelectedIndex;
		ListBox14.Items.RemoveAt(ListBox14.SelectedIndex);
		string text = null;
		checked
		{
			IEnumerator enumerator = default(IEnumerator);
			try
			{
				enumerator = ListBox14.Items.GetEnumerator();
				while (enumerator.MoveNext())
				{
					string text2 = Conversions.ToString(enumerator.Current);
					text = text + Conversions.ToString(Conversion.Val(text2.Substring(0, text2.IndexOf(" ") - 1).Remove(0, 2))) + ",";
				}
			}
			finally
			{
				if (enumerator is IDisposable)
				{
					(enumerator as IDisposable).Dispose();
				}
			}
			try
			{
				ListBox14.SelectedIndex = selectedIndex - 1;
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				ProjectData.ClearProjectError();
			}
			if (Operators.CompareString(text, null, TextCompare: false) == 0)
			{
				TextBox4.Text = null;
				return;
			}
			if (text.EndsWith(","))
			{
				text = text.Remove(text.Length - 1);
			}
			TextBox4.Text = text;
		}
	}

