	private void Button165_Click(object sender, EventArgs e)
	{
		TextBox textBox = TextBox34;
		Button9.BackColor = Color.Red;
		Button9.BackgroundImage = Resources.public_button;
		TextBox textBox2 = textBox;
		int selectionStart = textBox2.SelectionStart;
		bool flag = true;
		try
		{
			int num = textBox2.Text.Substring(selectionStart).IndexOf(">");
			int num2 = textBox2.Text.Substring(selectionStart).IndexOf("<");
			flag = ((num <= num2) ? true : false);
			flag = ((!(num == -1 && num2 == -1)) ? true : false);
		}
		catch (Exception ex)
		{
			ProjectData.SetProjectError(ex);
			Exception ex2 = ex;
			ProjectData.ClearProjectError();
		}
		int num3 = -1;
		string search = null;
		if (flag)
		{
			try
			{
				num3 = textBox2.Text.Substring(0, selectionStart).LastIndexOf("<");
				flag = num3 > -1;
			}
			catch (Exception ex3)
			{
				ProjectData.SetProjectError(ex3);
				Exception ex4 = ex3;
				flag = false;
				ProjectData.ClearProjectError();
			}
		}
		if (flag)
		{
			try
			{
				if (Operators.CompareString(textBox2.Text.Substring(num3, textBox2.Text.Substring(num3).IndexOf("=")).Trim(), "<img id", TextCompare: false) == 0)
				{
					flag = true;
				}
				else
				{
					flag = false;
				}
				search = checked(textBox2.Text.Substring(num3 + 8, textBox2.Text.Substring(num3 + 8).IndexOf(" ")));
			}
			catch (Exception ex5)
			{
				ProjectData.SetProjectError(ex5);
				Exception ex6 = ex5;
				flag = false;
				ProjectData.ClearProjectError();
			}
		}
		Module1.FManagerShowV2(p13, textBox, search);
	}

