	private void diag_copyZip_ok_Click(object sender, EventArgs e)
	{
		bool flag = false;
		checked
		{
			IEnumerator enumerator = default(IEnumerator);
			try
			{
				enumerator = ComboBox4.Items.GetEnumerator();
				while (enumerator.MoveNext())
				{
					string obj = Conversions.ToString(enumerator.Current);
					if (Operators.CompareString(obj.Substring(obj.IndexOf(" ") + 1).Trim(), TextBox12.Text.Trim(), TextCompare: false) == 0)
					{
						CustomMsgBox.CMsgBox("이미 존재하는 이름입니다.", "알림", "닫기", custom_msgbox.CMsgboxColor.DarkGreen, custom_msgbox.CmsgBoxIcon.icon_Exclamation, custom_msgbox.ShowLocation.MiddleCenter, autoClose: true, 500);
						flag = true;
						break;
					}
				}
			}
			finally
			{
				if (enumerator is IDisposable)
				{
					(enumerator as IDisposable).Dispose();
				}
			}
			if (flag)
			{
				return;
			}
			string hTML = new GetHtmlClass(Module1._dburl + "/set.php", "p=" + MySettingsProperty.Settings.pw + "&t=cloneKeyZip&nm=" + Module1.UrlEncode(ComboBox4.Text.Substring(ComboBox4.Text.IndexOf(" ") + 1)) + "&rename=" + Module1.UrlEncode(diag_copyZip_text.Text.Trim()), progress: true).getHTML(MyProject.Forms.mlas);
			try
			{
				string[] array = hTML.Split(new string[1] { "|" }, StringSplitOptions.None);
				if (Operators.CompareString(array[0], "correct", TextCompare: false) == 0)
				{
					CustomMsgBox.CMsgBox(TextBox12.Text + " 키워드집을 복제했습니다.", "새로 만들기", "닫기", custom_msgbox.CMsgboxColor.DarkGreen, custom_msgbox.CmsgBoxIcon.icon_Information, custom_msgbox.ShowLocation.BottomRight, autoClose: true);
					diag_copyZip.Hide();
					ComboBox4.Items.Add(array[1] + ":" + TextBox12.Text);
					ZipList();
					ComboBox4.SelectedIndex = ComboBox4.Items.Count - 1;
				}
				else
				{
					CustomMsgBox.CMsgBox("키워드집 복제 실패." + array[1], "알 수 없는 오류입니다.", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
					diag_copyZip.Hide();
				}
			}
			catch (Exception ex)
			{
				ProjectData.SetProjectError(ex);
				Exception ex2 = ex;
				CustomMsgBox.CMsgBox("키워드집 복제 실패.", "알 수 없는 오류입니다.", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
				diag_copyZip.Hide();
				ProjectData.ClearProjectError();
			}
			diag_copyZip.Hide();
		}
	}

