			}
		}
		openFileDialog = null;
	}

	private void keywordUpload(string[] filenames)
	{
		checked
		{
			foreach (string text in filenames)
			{
				ImageFormat imageFormat = null;
				string left = text.Substring(text.LastIndexOf(".") + 1).ToLower();
				if (Operators.CompareString(left, "jpg", TextCompare: false) == 0)
				{
					imageFormat = ImageFormat.Jpeg;
					string str = Module1.ImageToBase64(text, imageFormat);
					string hTML = new GetHtmlClass(Module1._dburl + "/set.php?t=keywordFileUpload", "p=" + MySettingsProperty.Settings.pw + "&n=" + TextBox9.Text + "&d=" + HttpUtility.UrlEncode(str), progress: true).getHTML(MyProject.Forms.mlas);
					if (hTML.Equals("incorrect"))
					{
						CustomMsgBox.CMsgBox(text + " 파일 업로드 중에 오류가 발생했습니다.", "업로드 실패", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
						continue;
					}
					int result = 0;
					if (int.TryParse(hTML, out result))
					{
						ListBox16.Items.Add(hTML);
						sjka_cyber.keyword_imagelist.Add(new sjka_cyber_keyimage(hTML, ""));
						try
						{
							ListBox16.ClearSelected();
						}
						catch (Exception ex)
						{
							ProjectData.SetProjectError(ex);
							Exception ex2 = ex;
							ProjectData.ClearProjectError();
						}
						try
						{
							ListBox16.SelectedIndex = ListBox16.Items.Count - 1;
						}
						catch (Exception ex3)
						{
							ProjectData.SetProjectError(ex3);
							Exception ex4 = ex3;
							ProjectData.ClearProjectError();
						}
					}
					else
					{
						CustomMsgBox.CMsgBox(text + " 파일 업로드 중에 오류가 발생했습니다.", "업로드 실패", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
					}
				}
				else
				{
					CustomMsgBox.CMsgBox("JPG 이미지 파일만 업로드 가능합니다.", "업로드 실패", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
				}
			}
		}
	}

