	private void Button184_Click(object sender, EventArgs e)
	{
		if (NoExistImage || PictureBox25.Image == null || ListBox16.SelectedIndex < 0 || MessageBox.Show(Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject("번호 ", ListBox16.SelectedItem), "\r\n"), "\r\n"), "이미지를 교체 하시겠습니까?")), "확인", MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.No)
		{
			return;
		}
		OpenFileDialog openFileDialog = new OpenFileDialog();
		openFileDialog.Multiselect = false;
		if (openFileDialog.ShowDialog() == DialogResult.OK)
		{
			ImageFormat imageFormat = null;
			switch (openFileDialog.FileName.Substring(checked(openFileDialog.FileName.LastIndexOf(".") + 1)).ToLower())
			{
			case "png":
				imageFormat = ImageFormat.Png;
				break;
			case "jpg":
				imageFormat = ImageFormat.Jpeg;
				break;
			case "gif":
				imageFormat = ImageFormat.Gif;
				break;
			case "bmp":
				imageFormat = ImageFormat.Bmp;
				break;
			default:
				CustomMsgBox.CMsgBox(openFileDialog.FileName + " 이미지 파일만 업로드 가능합니다.", "업로드 실패", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
				return;
			}
			string text = Module1.ImageToBase64(openFileDialog.FileName, imageFormat);
			PictureBox25.Image = Base64ToImage(text);
			if (Operators.CompareString(new GetHtmlClass(Module1._dburl + "/set.php?t=keywordFileChange", Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject("p=" + MySettingsProperty.Settings.pw + "&n=", ListBox16.SelectedItem), "&d="), HttpUtility.UrlEncode(text))), progress: true).getHTML(MyProject.Forms.mlas), "correct", TextCompare: false) != 0)
			{
				CustomMsgBox.CMsgBox(openFileDialog.FileName + " 파일 업로드 중에 오류가 발생했습니다.", "업로드 실패", "닫기", custom_msgbox.CMsgboxColor.Red, custom_msgbox.CmsgBoxIcon.icon_Error);
				return;
			}
		}
		openFileDialog = null;
	}

